<?php
ini_set('display_errors','0');require_once __DIR__.'/confirmed_access.php';require_once dirname(__DIR__,2).'/krf_enquiry_followup/helpers.php';header('Content-Type: application/json; charset=utf-8');
try{mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);$scope=confirmedAjaxContext(false);$token=(string)($_POST['token']??'');$krfconn->begin_transaction();$rows=efLockConversion($krfconn,$token,$scope);if(!$rows)throw new RuntimeException('Enquiry token required.');$first=$rows[0];$clientIds=array_unique(array_filter(array_column($rows,'clientid')));
 $clients=efQuery($krfconn,'SELECT * FROM krf_client_master WHERE companyid=? AND subcompanyid=? AND projectid=?',array_slice($scope,0,3));$matches=[];$phone=efPhone($first['mobileno']);foreach($clients as $c){$phones=preg_split('/[,;\/\s]+/',(string)$c['phones']);foreach($phones as $number)if(efPhone($number)===$phone){$matches[]=$c;break;}}
 $products=efQuery($krfconn,"SELECT ProductID,sku,ProductName,IsGrafted,PriceOfProduct,Status FROM product_master WHERE projectid=? AND LOWER(TRIM(Status))='active' ORDER BY ProductName",[$scope[2]]);$items=[];
 $krfconn->commit();echo json_encode(['status'=>'success','admin'=>(bool)($_SESSION['enquiry_po'][$token]['admin']??false),'header'=>['clientid'=>'','clientname'=>$first['clientname'],'mobileno'=>$first['mobileno'],'emailid'=>$first['emailid'],'delivery_address'=>$first['address'],'statename'=>$first['statename'],'districtname'=>$first['districtname']],'client'=>['cityname'=>$first['cityname'],'stateid'=>$first['stateid'],'districtid'=>$first['districtid'],'invoicing_address'=>$first['address']],'matches'=>$matches,'ids'=>array_map('intval',array_column($rows,'id')),'items'=>$items,'products'=>$products]);
}catch(Throwable $e){if(isset($krfconn))try{$krfconn->rollback();}catch(Throwable $ignored){}http_response_code(400);echo json_encode(['status'=>'error','message'=>$e->getMessage()]);}
